<script setup lang="ts">
import {qualityText as qt} from '../shared/i18n'

import {reactive} from 'vue'
import {useTemplatePage} from '../hooks/useTemplatePage'
const props=defineProps<{level:number}>(),vm=reactive(useTemplatePage(props.level))
</script>
<template><a-card :title="(level===1?qt('company'):qt('project2'))+qt('taskTemplate')">
 <template #extra><a-space><a-button @click="vm.load">{{qt('refresh')}}</a-button><a-button v-if="vm.can('quality-configuration','save')" type="primary" @click="vm.start()">{{qt('newTemplate')}}</a-button></a-space></template><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon />
 <a-select v-model:value="vm.projectId" show-search option-filter-prop="label" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" allow-clear style="width:240px;margin-bottom:16px" :placeholder="qt('businessProject')" />
 <a-space wrap style="margin-bottom:16px"><a-input-search v-model:value="vm.filterName" :placeholder="qt('templateName')" /><a-select v-model:value="vm.filterType" :options="[{value:1,label:qt('taskTemplate')},{value:2,label:qt('configurationTemplateLibrary')}]" :placeholder="qt('type')" style="width:180px" allow-clear /><a-select v-model:value="vm.filterLine" :options="vm.lineOptions" :placeholder="qt('inspectionLine')" style="width:180px" allow-clear /><a-select v-model:value="vm.filterStatus" :options="[{value:1,label:qt('enabled')},{value:0,label:qt('disabled')}]" :placeholder="qt('status')" style="width:140px" allow-clear /></a-space>
 <a-table :locale="level===2&&!vm.projectId?{emptyText:qt('selectBusinessProject')}:{}" :data-source="vm.displayRows" :loading="vm.loading" row-key="id"><a-table-column :title="qt('templateName')" data-index="name" /><a-table-column :title="qt('businessProject')" data-index="projectName" /><a-table-column :title="qt('type')" key="type"><template #default="{record}">{{record.data.templateType===2?qt('configurationTemplateLibrary'):qt('taskTemplate')}}</template></a-table-column><a-table-column :title="qt('totalScore')" key="score"><template #default="{record}">{{record.data.totalScore}}</template></a-table-column><a-table-column :title="qt('status')" key="status"><template #default="{record}">{{record.status?qt('enabled'):qt('disabled')}}</template></a-table-column><a-table-column :title="qt('actions')" key="actions"><template #default="{record}"><a-space><a-button type="link" @click="vm.start(record,false,true)">{{qt('view')}}</a-button><template v-if="vm.can('quality-configuration','save')"><a-button type="link" @click="vm.start(record)">{{qt('edit')}}</a-button><a-button type="link" @click="vm.start(record,true)">{{qt('createFromTemplate')}}</a-button></template><a-popconfirm v-if="vm.can('quality-configuration','delete')" :title="qt('deleteThisTemplate')" @confirm="vm.remove(record)"><a-button danger type="link">{{qt('delete')}}</a-button></a-popconfirm></a-space></template></a-table-column></a-table>
 <a-drawer v-model:open="vm.open" :title="vm.viewOnly?qt('templateDetails'):vm.form.id?qt('editTemplate'):qt('newTemplate')" width="880"><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-form layout="vertical" :model="vm.form" :disabled="vm.viewOnly" @finish="vm.save">
 <a-form-item :label="qt('templateName')" name="name" :rules="[{required:true,message:qt('enterTheTemplateName')}]"><a-input v-model:value="vm.form.name" :maxlength="128" /></a-form-item><a-form-item :label="qt('templateType')"><a-radio-group v-model:value="vm.form.data.templateType"><a-radio :value="1">{{qt('taskTemplate')}}</a-radio><a-radio :value="2">{{qt('configurationTemplateLibrary')}}</a-radio></a-radio-group></a-form-item><a-form-item :label="qt('taskDescription')"><a-textarea v-model:value="vm.form.data.taskDescription" /></a-form-item>
 <a-form-item v-if="level===1" :label="qt('businessProject')" name="projectId" :rules="[{required:true,message:qt('selectBusinessProject')}]"><a-select v-model:value="vm.form.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" show-search option-filter-prop="label" :disabled="!!vm.form.id" @change="vm.changeFrequency" /></a-form-item>
 <a-form-item v-else :label="qt('inspectionCycle')" :name="['data','inspectionFrequency']" :rules="[{required:true}]"><a-select v-model:value="vm.form.data.inspectionFrequency" :options="[{value:1,label:qt('daily')},{value:2,label:qt('weekly')},{value:3,label:qt('monthly')}]" @change="vm.changeFrequency" /></a-form-item>
 <a-form-item :label="qt('checkItem')"><a-select :value="vm.selected" mode="multiple" :options="vm.availableConfigs.map(c=>({value:c.id,label:[c.data.subjectParentName,c.data.parentName,c.name].filter(Boolean).join(' / ')}))" @change="(v:unknown)=>vm.select(v as string[])" show-search option-filter-prop="label" /></a-form-item>
 <a-table :data-source="vm.form.data.configItems" :pagination="false" row-key="configId" size="small"><a-table-column :title="qt('checkItem')" key="name"><template #default="{record}">{{vm.configName(record.configId)}}</template></a-table-column><a-table-column :title="qt('points')" key="score"><template #default="{record}"><a-input-number v-model:value="record.score" :precision="0" :min="0" :max="100" :disabled="vm.viewOnly" /></template></a-table-column><a-table-column :title="qt('deductionRule')" key="deduct"><template #default="{record}"><a-input v-model:value="record.deductionStandard" :disabled="vm.viewOnly" /></template></a-table-column></a-table>
 <a-divider>{{qt('totalScore')}} {{vm.total}}</a-divider><template v-if="level===1"><h3>{{qt('lineWeightsTotal')}} {{vm.weightTotal}}%）</h3><a-form-item v-for="weight in vm.form.data.lineWeights" :key="weight.subjectParentId" :label="weight.subjectParentName||weight.subjectParentId"><a-input-number v-model:value="weight.weight" :min="0" :max="100" addon-after="%" /></a-form-item></template>
 <a-form-item :label="qt('status')"><a-switch :checked="vm.form.status===1" @change="(v:unknown)=>vm.form.status=v?1:0" /></a-form-item><a-button v-if="!vm.viewOnly" type="primary" html-type="submit" :loading="vm.saving">{{qt('saveTemplate')}}</a-button></a-form></a-drawer>
 </a-card></template>
